insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$buritama$q$, $q$https://sapl.buritama.sp.leg.br/norma/5379 (Lei 4.704/2021) ; https://sapl.buritama.sp.leg.br/norma/5924 (Decreto 4.537/2021, rota pelo anel viário)$q$, $q$Atos oficiais de Buritama: domínio público (Lei 9.610/1998 art. 8º IV). Zona: IBGE, Malha de Setores Censitários do Censo 2022 (dados públicos, citar a fonte: IBGE), com o acesso estadual recortado sobre o OpenStreetMap (ODbL 1.0).$q$, 1, $q$Lei 4.704/2021, art. 1º: tráfego de caminhões a partir de 5 eixos proibido nas vias públicas da cidade (longos pesados), com rota obrigatória pelo anel viário; carga e descarga e moradores com autorização (art. 2º). Correção do verificador: alvo só eixos > 4 (a lista de combinações é exemplificativa). Eficácia condicionada à sinalização (Dec. 4.537/2021, art. 4º), não conferida.$q$);
